-- Stage 9 checks. Read-only. Run: sqlcmd -S localhost -E -d EEMSuite_Northlake -W -s "|" -i checks.sql
-- Hierarchy/meters from Stages 2-7 are running in parallel with this stage, so several checks return 0 rows until
-- those land -- that is expected here, not a failure.
-- HMR configuration and history are checked separately below; missing history remains incomplete.
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;

PRINT '== projects_with_finance: 5 rows, CapitalCost/Incentives populated, ProjectType joins to the right ProjectCategory (the fifth is Ridgeline''s WTG-07 Gearbox Replacement, Renewable Energy / Wind) ==';
SELECT p.ProjectID, p.Description, pt.Description AS ProjectType, pc.Description AS ProjectCategory,
       p.StartDate, p.EndDate, p.CapitalCost, p.Incentives, p.TrackingNumber
FROM dbo.Project p JOIN dbo.ProjectType pt ON pt.ProjectTypeID = p.ProjectTypeID
JOIN dbo.ProjectCategory pc ON pc.ProjectCategoryID = pt.ProjectCategoryID
ORDER BY p.ProjectID;
GO

PRINT '== alarm_definitions: 15 point alarm rows once Stage 2/3 points exist (0 rows until then): the 4 campus and Cedar Row alarms, the 10 Ridgeline Turbine State alarms (digital, so no thresholds) and the met mast high-wind alarm; an alarm is a point with alarms on and a notify user or group on its node ==';
SELECT p.PtID, w.ReportName AS PointName, p.PtType, p.Priority, p.HiHi AS HighAlarm, p.Hi AS HighWarning, p.Lo AS LowWarning, p.LoLo AS LowAlarm,
       p.AlarmDeadband, p.NormalState, w.PrimaryUserID AS NotifyUser, w.NotifyGroupID AS NotifyGroup
FROM dbo.PointDef_TBL p JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
WHERE p.DisableAlarms = 0 AND (w.PrimaryUserID IS NOT NULL OR w.NotifyGroupID IS NOT NULL)
ORDER BY p.PtID;
GO

PRINT '== alarms_lifecycle: raised/ack/resolved AlarmData rows across priorities, 0 until the alarm task has run against real data (WTG-07''s Fault, 2025-02-11 to 2025-04-22, is the known Ridgeline event) ==';
SELECT a.PtID, a.SeverityNbr, a.Priority, a.Ack, a.Resolved, a.PtTimeStamp
FROM dbo.AlarmData_TBL a ORDER BY a.PtTimeStamp DESC;
GO

PRINT '== ridgeline_wtg07_fault: each Ridgeline Turbine State point''s change-of-state rows; WTG-07 shows Value 2 (Fault) from 2025-02-11 and a return to 1 (Running) at the end of the outage, and Severity shows what Normal State does to a digital alarm ==';
SELECT m.Description AS Meter, a.PtTimeStamp, a.Value, a.SeverityNbr, a.Priority, a.Resolved
FROM dbo.AlarmData_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
JOIN dbo.MetaWorld_TBL m ON m.MetaWorldID = w.ParentID
WHERE m.Description LIKE 'Ridgeline WTG-%' AND w.Description = 'Turbine State'
ORDER BY m.Description, a.PtTimeStamp;
GO

PRINT '== audit_trail: AuditLog rows from the three bill/account/meter field edits ==';
SELECT l.LogID, c.Description AS FieldTracked, l.UserID, l.AsOfDate, l.PreviousValue, l.CurrentValue
FROM dbo.AuditLog l JOIN dbo.AuditConfig c ON c.AuditID = l.AuditID
ORDER BY l.AsOfDate DESC;
GO

PRINT '== activity_trail: logins and report-view activity per user, 0 for casey.holt (Inactive, must never appear); the two Ridgeline researchers (Northlake University users reading the plant''s site) show their own logins and report views ==';
SELECT u.UserName, COUNT(DISTINCT ul.LogID) AS Logins, COUNT(DISTINCT g.AccessDate) AS ReportViews
FROM dbo.Users u LEFT JOIN dbo.UserLogin_Tbl ul ON ul.UserID = u.UserID
LEFT JOIN dbo.GuiReportActivityLog g ON g.UserID = u.UserID
WHERE u.UserName IN ('samantha.ireland','jordan.hale','maya.chen','dana.okafor','avery.singh','quinn.roberts','casey.holt','elena.vasquez','kai.nakamura')
GROUP BY u.UserName ORDER BY u.UserName;
GO

PRINT '== task_schedules: the 12 standard tasks scheduled, plus the 2 custom workflow tasks and the 1 custom Nightly Campus Load Summary task ==';
SELECT ti.TaskItemID, t.Name AS Task, ti.Active, ts.ScheduleKind, ts.IntervalSeconds, ts.CronExpression
FROM dbo.TaskItems ti JOIN dbo.Task_Tbl t ON t.TaskID = ti.TaskID
LEFT JOIN dbo.TaskSchedules ts ON ts.TaskScheduleId = ti.TaskScheduleID
ORDER BY t.TaskID;
GO

PRINT '== task_history: TaskLog rows and WorkflowRun rows once tasks have executed (0 until then) ==';
SELECT TOP 20 TaskLogID, ApplicationName, LogTimeStamp, LogMessage FROM dbo.TaskLog ORDER BY LogTimeStamp DESC;
GO
SELECT TOP 20 WorkflowRunId, WorkflowName, StartedAt, EndedAt, Succeeded, ErrorCount FROM dbo.WorkflowRun ORDER BY StartedAt DESC;
GO

PRINT '== saved_reports_and_dashboards: 18 saved reports, 3 dashboards, 2 favorite-based custom views (20 saved-report rows; the view lists only what the signed-in user owns or is shared) ==';
SELECT GUIMFRSavedReportsID, Title, ModuleName, Dashboardable FROM dbo.GUIMFRSavedReports ORDER BY GUIMFRSavedReportsID;
GO
SELECT GUIMFRDashboardID, Title, PublicFlag FROM dbo.GUIMFRDashboards ORDER BY GUIMFRDashboardID;
GO

PRINT '== ridgeline_saved_reports_and_shares: Mateo owns the farm trend, the WTG-07 trend and Gateway Status (3 reports) and the Ridgeline Operations dashboard (3 tiles, shared with ntp_wind_ops); Elena owns the 10 power curves, each shared with eem_ridgeline_research; the monthly performance report belongs to the delivery author ==';
SELECT u.UserName AS Owner, r.Title, p.CompanyID AS SharedWithCompany, p.GroupID AS SharedWithGroup
FROM dbo.GUIMFRSavedReports_TBL r JOIN dbo.Users_TBL u ON u.UserID = r.UserID
LEFT JOIN dbo.GuiMFRPermissions_TBL p ON p.GuiMFRSavedReportsID = r.GuiMFRSavedReportsID
WHERE r.Title LIKE 'Ridgeline%' ORDER BY u.UserName, r.Title;
GO
SELECT u.UserName AS Owner, d.Title, d.PublicFlag, p.CompanyID AS SharedWithCompany, p.GroupID AS SharedWithGroup,
       (SELECT COUNT(*) FROM dbo.GUIMFRDashboardReports dr WHERE dr.GUIMFRDashboardID = d.GUIMFRDashboardID) AS Tiles
FROM dbo.GUIMFRDashboards d JOIN dbo.Users_TBL u ON u.UserID = d.UserID
LEFT JOIN dbo.GuiMFRPermissions_TBL p ON p.GUIMFRDashboardID = d.GUIMFRDashboardID
WHERE d.Title LIKE 'Ridgeline%' ORDER BY d.Title;
GO

PRINT '== mfr_delivery_100plus: Monthly Building Energy delivery resolves to >=100 recipients through its groups (the Ridgeline monthly performance delivery resolves to 2, Mateo and Elena) ==';
SELECT d.MFRDeliveryID, d.Description, d.IncludePDF, d.IncludeExcel, d.CronExpression,
       SUM(CASE WHEN r.RecipientKind = 'Group' THEN gm.MemberCount ELSE 1 END) AS ResolvedRecipients
FROM dbo.MFRDelivery_TBL d
JOIN dbo.MFRDeliveryRecipient_TBL r ON r.MFRDeliveryID = d.MFRDeliveryID
OUTER APPLY (SELECT COUNT(*) AS MemberCount FROM dbo.UserGroupMember m WHERE m.GroupID = r.GroupID) gm
GROUP BY d.MFRDeliveryID, d.Description, d.IncludePDF, d.IncludeExcel, d.CronExpression
ORDER BY d.MFRDeliveryID;
GO

PRINT '== mfr_external_email_finding: Email column exists on MFRDeliveryRecipient_TBL but every row here has Email NULL -- the picker never writes it (product backlog item 8) ==';
SELECT MFRDeliveryRecipientID, MFRDeliveryID, RecipientKind, UserID, GroupID, Email
FROM dbo.MFRDeliveryRecipient_TBL WHERE Email IS NOT NULL;
GO

